package com.securemail.crypto

import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.ConcurrentHashMap
import java.time.Instant
import java.security.MessageDigest
import java.security.SecureRandom
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.GCMParameterSpec

object EmailCryptoService {
  private val rateLimiter = new ConcurrentHashMap[String, RateState]()
  private val MAX_RETRIES = 3
  private val RATE_LIMIT_WINDOW_MS = 60000L
  private val MAX_REQUESTS_PER_WINDOW = 100
  private val GCM_IV_LENGTH = 12
  private val GCM_TAG_LENGTH_BITS = 128
  private val secureRandom = new SecureRandom()

  case class RateState(count: AtomicInteger, windowStart: Long)

  case class EmailEnvelope(
    sender: String,
    recipient: String,
    subject: String,
    body: String,
    customHeaders: Map[String, String] = Map.empty
  )

  case class SignedEnvelope(
    rawHeaders: String,
    encryptedBody: String,
    signature: String
  )

  private def checkRateLimit(clientId: String): Boolean = {
    val now = System.currentTimeMillis()
    val state = rateLimiter.computeIfAbsent(clientId, _ => RateState(new AtomicInteger(0), now))
    if (now - state.windowStart > RATE_LIMIT_WINDOW_MS) {
      rateLimiter.put(clientId, RateState(new AtomicInteger(1), now))
      true
    } else {
      state.count.incrementAndGet() <= MAX_REQUESTS_PER_WINDOW
    }
  }

  private def encryptBody(body: String, key: Array[Byte]): String = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val secretKey = new SecretKeySpec(key, "AES")
    val iv = new Array[Byte](GCM_IV_LENGTH)
    secureRandom.nextBytes(iv)
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv)
    cipher.init(Cipher.ENCRYPT_MODE, secretKey, spec)
    val ciphertext = cipher.doFinal(body.getBytes("UTF-8"))
    // Prepend the IV so it can be recovered for decryption
    val combined = new Array[Byte](iv.length + ciphertext.length)
    System.arraycopy(iv, 0, combined, 0, iv.length)
    System.arraycopy(ciphertext, 0, combined, iv.length, ciphertext.length)
    Base64.getEncoder.encodeToString(combined)
  }

  private def computeSignature(data: String, key: Array[Byte]): String = {
    val mac = javax.crypto.Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(key, "HmacSHA256"))
    Base64.getEncoder.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }

  private def sanitizeHeaderValue(value: String): String = {
    // Remove obvious CRLF sequences for header safety
    value.replace("\r\n", "").replace("\r", "").replace("\n", "")
  }

  private def encodeHeaderValue(value: String): String = {
    // RFC 2047 encoding for non-ASCII characters
    if (value.forall(c => c >= 0x20 && c <= 0x7E)) {
      value
    } else {
      "=?UTF-8?B?" + Base64.getEncoder.encodeToString(value.getBytes("UTF-8")) + "?="
    }
  }

  private def buildHeaders(envelope: EmailEnvelope): String = {
    val baseHeaders = List(
      s"From: ${sanitizeHeaderValue(envelope.sender)}",
      s"To: ${sanitizeHeaderValue(envelope.recipient)}",
      s"Subject: ${encodeHeaderValue(sanitizeHeaderValue(envelope.subject))}",
      s"Date: ${Instant.now().toString}",
      s"X-Mailer: SecureCrypto/1.0"
    )

    val customHeaderLines = envelope.customHeaders.map { case (k, v) =>
      val sanitizedKey = sanitizeHeaderValue(k)
      val sanitizedValue = sanitizeHeaderValue(v)
      // Truncate long header values to prevent abuse
      val truncatedValue = if (sanitizedValue.length > 76) {
        sanitizedValue.take(76)
      } else {
        sanitizedValue
      }
      s"$sanitizedKey: $truncatedValue"
    }.toList

    (baseHeaders ++ customHeaderLines).mkString("\r\n")
  }

  def sendSignedEmail(
    envelope: EmailEnvelope,
    encryptionKey: Array[Byte],
    signingKey: Array[Byte],
    clientId: String
  ): Either[String, SignedEnvelope] = {
    if (!checkRateLimit(clientId)) {
      return Left("Rate limit exceeded")
    }

    var lastError: String = ""
    var attempt = 0

    while (attempt < MAX_RETRIES) {
      try {
        val headers = buildHeaders(envelope)
        val encrypted = encryptBody(envelope.body, encryptionKey)
        val signatureInput = headers + "\r\n\r\n" + encrypted
        val signature = computeSignature(signatureInput, signingKey)

        return Right(SignedEnvelope(
          rawHeaders = headers,
          encryptedBody = encrypted,
          signature = signature
        ))
      } catch {
        case e: Exception =>
          lastError = e.getMessage
          attempt += 1
          Thread.sleep(Math.min(1000L * attempt, 3000L))
      }
    }

    Left(s"Failed after $MAX_RETRIES attempts: $lastError")
  }
}
